class DriveMultipartTest {
    @Test fun mimeParserCanReadMetadataAndFullUtf8Backup() {
        val data = AppData(settings = AppSettings(monthlySalary = 12345.0, creditPoints = 3.5,
            pensionPercent = 7.0, reasons = listOf("עבודה מהבית")))
        val metadata = JSONObject().put("name", "backup.json").put("mimeType", "application/json").toString()
        val boundary = "workhours_test"
        val bytes = driveMultipartBody(metadata, backupText(data), boundary).toByteArray(Charsets.UTF_8)
        val body = bytes.toString(Charsets.UTF_8)
        assertFalse(body.contains("\\r"))
        assertFalse(body.replace("\r\n", "").contains('\n'))
        assertTrue(body.endsWith("\r\n--$boundary--\r\n"))
        val parts = body.split("--$boundary\r\n").drop(1)
        assertEquals(2, parts.size)
        val first = parts[0].split("\r\n\r\n", limit = 2)
        assertEquals("Content-Type: application/json; charset=UTF-8", first[0])
        assertEquals("backup.json", JSONObject(first[1].removeSuffix("\r\n")).getString("name"))
        val payload = parts[1].substringAfter("\r\n\r\n").substringBefore("\r\n--$boundary--")
        assertEquals(data, readBackup(payload))
    }
    @Test fun unsafeBoundaryCannotInjectHeaders() {
        assertThrows(IllegalArgumentException::class.java) {
            driveMultipartBody("{}", "{}", "boundary\r\nInjected: bad")
        }
    }
}
